-- public.feed_in_pack(p_world uuid, p_uid uuid, p_species text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.feed_in_pack(p_world uuid, p_uid uuid, p_species text, p_target jsonb)
 RETURNS item
 LANGUAGE plpgsql
 STABLE
AS $function$
declare v_it item;
begin
  select i.* into v_it from item i
   where i.world_id = p_world and i.holder = 'player' and i.holder_uid = p_uid
     and (is_bait_for(p_species, i.def) or i.def = whey_bucket())
     and (target_item(p_target) is null or i.id = target_item(p_target))
   order by i.id limit 1;
  return v_it;
end $function$
